test "every name looks itself up, in any case" {
    var upper: [64]u8 = undefined;
    for (names, 0..) |name, id| {
        try std.testing.expectEqual(@as(i32, @intCast(id)), lookup(name));
        try std.testing.expectEqual(@as(i32, @intCast(id)), lookup(std.ascii.upperString(&upper, name)));
    }
    try std.testing.expectEqual(@as(i32, -1), lookup("x-custom"));
    try std.testing.expectEqual(@as(i32, -1), lookup("content-typo"));
}
